 Add-Type -AssemblyName System.Windows.Forms,System.Drawing; Start-Sleep 2; $vs=[System.Windows.Forms.SystemInformation]::VirtualScreen; $bmp=[System.Drawing.Bitmap]::new($vs.Width,$vs.Height); $g=[System.Drawing.Graphics]::FromImage($bmp); $g.CopyFromScreen($vs.X,$vs.Y,0,0,$bmp.Size); $out=Join-Path ([Environment]::GetFolderPath('Desktop')) ('screenshot_{0:yyyyMMdd_HHmmss}.png' -f (Get-Date)); $bmp.Save($out,[System.Drawing.Imaging.ImageFormat]::Png); $g.Dispose(); $bmp.Dispose(); Write-Host "Saved: $out"
